func freebsd_mapShared(f *os.Freebsd_File, length uint64, off, page int64) Ptr {
	name := f.Name()
	if abs, err := filepath.Freebsd_Abs(name); err == nil {
		name = abs
	}
	k := sharedKey{name, off, int64(length)}
	sharedMu.Lock()
	defer sharedMu.Unlock()
	if p, ok := sharedMaps[k]; ok {
		return p
	}
	p := mallocAligned(uintptr(page), uintptr(length))
	if _, err := f.ReadAt(freebsd_bytesAt(p, uintptr(length)), off); err != nil && err != io.EOF {
		setErrnoOf(err)
		return mapFailed
	}
	sharedMaps[k] = p
	return p
}
